#include "/home/reinsirk/Atcoder_Env/Verify/current/common/fast_io.hpp"
#include <algorithm>
#include <bit>
#include <cstdint>
#include <vector>
int main() {
    int n{}, q{}; if (!(verify_in >> n >> q)) return 0;
    const unsigned levels = std::bit_width(static_cast<unsigned>(n));
    std::vector<std::vector<int>> ancestors(levels, std::vector<int>(n));
    std::vector<int> depth(n);
    for (int v = 1; v < n; ++v) { int p{}; verify_in >> p; ancestors[0][v] = p; depth[v] = depth[p] + 1; }
    for (unsigned k = 1; k < levels; ++k)
        for (int v = 0; v < n; ++v) ancestors[k][v] = ancestors[k-1][ancestors[k-1][v]];
    while (q--) {
        int u{}, v{}; verify_in >> u >> v;
        if (depth[u] < depth[v]) std::swap(u, v);
        unsigned difference = static_cast<unsigned>(depth[u] - depth[v]);
        for (unsigned k = 0; difference; ++k, difference >>= 1) if (difference & 1) u = ancestors[k][u];
        if (u != v) {
            for (unsigned k = levels; k--;) if (ancestors[k][u] != ancestors[k][v]) { u = ancestors[k][u]; v = ancestors[k][v]; }
            u = ancestors[0][u];
        }
        verify_out << u << '\n';
    }
}

